from typing import List

class Solution:
    def sumIndicesWithKSetBits(self, nums: List[int], k: int) -> int:
        total_sum = 0
        for i in range(len(nums)):
            # Count set bits in index i using bin().count('1')
            if bin(i).count('1') == k:
                total_sum += nums[i]
        return total_sum
```

